// ThirdPlaceCatalog provides vetted third places, parks, and outdoor spots for "Touch Grass" routing.
type ThirdPlaceCatalog struct {
	places []domain.ThirdPlace
}

// Libraries, cafes and community centres from OpenStreetMap, generated by
// scripts/fetch_third_places.py. Data (c) OpenStreetMap contributors, ODbL.
//
//go:embed data/third_places.json
var thirdPlacesJSON []byte

// NewThirdPlaceCatalog returns the hand-picked places plus the OpenStreetMap dataset.
func NewThirdPlaceCatalog() *ThirdPlaceCatalog {
	c := newCuratedCatalog()
	var rows [][]any
	_ = json.Unmarshal(thirdPlacesJSON, &rows)
	// How "restorative" a stop is, loosely: used only to order suggestions.
	baseScore := map[string]float64{"library": 0.6, "community_centre": 0.45, "cafe": 0.4}
	label := map[string]string{"library": "Public library", "community_centre": "Community centre", "cafe": "Café",
		"restaurant": "Restaurant", "fast_food": "Quick bite"}
	for i, r := range rows {
		if len(r) < 6 {
			continue
		}
		cuisine, vegetarian := "", 0.0
		if len(r) >= 8 {
			cuisine, _ = r[6].(string)
			vegetarian, _ = r[7].(float64)
		}
		name, _ := r[0].(string)
		kind, _ := r[1].(string)
		lat, _ := r[2].(float64)
		lon, _ := r[3].(float64)
		wifi, _ := r[4].(float64)
		outdoor, _ := r[5].(float64)
		score := baseScore[kind]
		desc := label[kind]
		if outdoor == 1 {
			score += 0.15
			desc += " with outdoor seating"
		}
		c.places = append(c.places, domain.ThirdPlace{
			ID:          fmt.Sprintf("osm-%d", i),
			Name:        name,
			Type:        kind,
			Location:    domain.Location{Name: name, Latitude: lat, Longitude: lon},
			GreenScore:  score,
			Description: desc,
			HasWifi:     wifi == 1 || kind == "library",
			HasSeating:  true,

			Cuisine:        cuisine,
			Vegetarian:     vegetarian == 1,
			OutdoorSeating: outdoor == 1,
		})
	}
	return c
}

