// FindNearbyThirdPlaces returns up to `limit` places that can be visited
// between origin and dest with at most maxDetourMinutes of extra walking.
// With indoorOnly (bad weather) parks are left out. DetourMinutes on each
// result is the estimated extra time for THIS trip (straight-line distance at
// 12 min/km). Results favour green, close places and mix the place types.
func (c *ThirdPlaceCatalog) FindNearbyThirdPlaces(origin, dest domain.Location, maxDetourMinutes int, indoorOnly bool, limit int) []domain.ThirdPlace {
	direct := haversineDistance(origin.Latitude, origin.Longitude, dest.Latitude, dest.Longitude)

	type scored struct {
		place domain.ThirdPlace
		score float64
	}
	var matched []scored
	for _, p := range c.places {
		if indoorOnly && p.Type == "park" {
			continue
		}
		if p.Type == "restaurant" || p.Type == "fast_food" {
			continue // somewhere to eat is asked for, not suggested for a spare half hour
		}
		// Extra walking: either on the way, or a round trip from one end (the
		// realistic case when the commute itself is by transit).
		fromOrigin := haversineDistance(origin.Latitude, origin.Longitude, p.Location.Latitude, p.Location.Longitude)
		toDest := haversineDistance(p.Location.Latitude, p.Location.Longitude, dest.Latitude, dest.Longitude)
		extraKm := math.Min(fromOrigin+toDest-direct, math.Min(2*fromOrigin, 2*toDest))
		detour := int(math.Ceil(extraKm * 12))
		if detour > maxDetourMinutes {
			continue
		}
		p.DetourMinutes = detour
		// greener is better, every 10 minutes of detour costs 0.25
		matched = append(matched, scored{p, p.GreenScore - float64(detour)/40})
	}
	sort.Slice(matched, func(i, j int) bool {
		if matched[i].score != matched[j].score {
			return matched[i].score > matched[j].score
		}
		return matched[i].place.ID < matched[j].place.ID
	})

	// At most two of each type so the list is not five cafes.
	perType := map[string]int{}
	out := []domain.ThirdPlace{}
	for _, m := range matched {
		if perType[m.place.Type] >= 2 {
			continue
		}
		perType[m.place.Type]++
		out = append(out, m.place)
		if len(out) == limit {
			break
		}
	}
	return out
}

// Len is the number of places in the catalog.
func (c *ThirdPlaceCatalog) Len() int { return len(c.places) }

func haversineDistance(lat1, lon1, lat2, lon2 float64) float64 {
	const earthRadiusKm = 6371.0
	dLat := (lat2 - lat1) * (math.Pi / 180.0)
	dLon := (lon2 - lon1) * (math.Pi / 180.0)

	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*(math.Pi/180.0))*math.Cos(lat2*(math.Pi/180.0))*
			math.Sin(dLon/2)*math.Sin(dLon/2)

	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return earthRadiusKm * c
}
